draw:
(ctx, t, frame, total, W, H) => {
  ctx.fillStyle = '#06121f';
  ctx.fillRect(0, 0, W, H);
  // Concentric rings that ripple outward
  const cx = W/2, cy = H*0.55;
  for (let i = 0; i < 6; i++) {
    const phase = (t + i*0.12) % 1;
    const r = phase * Math.max(W, H) * 0.6;
    const alpha = 1 - phase;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI*2);
    ctx.lineWidth = 4;
    ctx.strokeStyle = `rgba(56, 189, 248, ${alpha*0.8})`;
    ctx.stroke();
  }
  // Orbiting dot
  const ang = t * Math.PI * 2;
  ctx.beginPath();
  ctx.arc(cx + Math.cos(ang)*Math.min(W,H)*0.28, cy + Math.sin(ang)*Math.min(W,H)*0.28, 14, 0, Math.PI*2);
  ctx.fillStyle = '#38bdf8';
  ctx.shadowColor = '#38bdf8';
  ctx.shadowBlur = 30;
  ctx.fill();
  ctx.shadowBlur = 0;
  // Title
  ctx.fillStyle = '#f8fafc';
  ctx.font = 'bold 72px Georgia, serif';
  ctx.textAlign = 'center';
  ctx.fillText('Ocean', cx, H*0.18);
  ctx.fillText('Plastic', cx, H*0.18 + 90);
  ctx.fillStyle = '#94a3b8';
  ctx.font = '24px Helvetica, Arial, sans-serif';
  ctx.fillText('A SHORT FILM', cx, H*0.18 + 150);
}
